/**
 * The generator: widgets.spec.json + its sources → widgets.generated.json (kit.widgets-generated.v1).
 *
 *   loadSpec(specPath) → { spec, text, dir }
 *   specProblems(spec) → string[]            (schema + references between ids)
 *   buildWidgets(specPath) → { generated, json, out }   deterministic: same inputs, same bytes
 *
 * Every widget instance is one archetype applied to one project scenario in one locale. Texts are resolved from the
 * spec (strings, {locale: string} maps), its content/OpenAPI/JSON Schema sources ({"$ref"}) and its engines
 * ({"$engine"}, called with build.asOf so the output only changes when an input changes).
 */
import { readFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { validateSchema } from "./schema.js";
import { kitRegistry, registryFor, composeSpecSchema, resolveBySchema } from "./registry.js";
import { loadSources, sourceRef, operation, engineCaller } from "./sources.js";
import { sha16, stable, isObj, addDays, plain } from "./util.js";
import SPEC_SCHEMA from "../schemas/widgets-spec.schema.json" with { type: "json" };
import PKG from "../package.json" with { type: "json" };

export const GENERATED_SCHEMA = "kit.widgets-generated.v1";
export const ENGINE_VERSION = `@saasreport/widgets ${PKG.version}`;
export const NOTICE = "Generated by `kit widgets build` from widgets.spec.json and its sources. Do not edit: change the spec or a source and rebuild; `kit widgets check` fails when this file is stale.";
const DIGITS = { fa: "arabext", ar: "arab" };

export function loadSpec(specPath) {
  const file = resolve(specPath);
  let text;
  try { text = readFileSync(file, "utf8"); } catch (e) { throw new Error(`cannot read ${specPath} (${e.code || e.message})`); }
  let spec;
  try { spec = JSON.parse(text); } catch (e) { throw new Error(`${specPath} is not JSON (${e.message})`); }
  // spec parts (generated families): their sources, audiences, use cases and scenarios join the spec's own
  const parts = [];
  for (const inc of spec.includes || []) {
    const pf = resolve(dirname(file), inc);
    let pt; try { pt = readFileSync(pf, "utf8"); } catch (e) { throw new Error(`${specPath}: includes ${inc}: cannot read (${e.code || e.message})`); }
    let part; try { part = JSON.parse(pt); } catch (e) { throw new Error(`${inc} is not JSON (${e.message})`); }
    parts.push(`${inc}\n${pt}`);
    for (const k of ["audiences", "useCases", "scenarios"]) if (part[k]) spec[k] = [...(spec[k] || []), ...part[k]];
    if (part.sources) spec.sources = { ...spec.sources, ...part.sources };
  }
  return { spec, text: parts.length ? [text, ...parts].join("\n") : text, file, dir: dirname(file) };
}

/** Schema problems, then references: use cases, audiences, actors, sources, archetypes, ids unique. */
const composed = new WeakMap();
/** kit.widgets-spec.v1 composed with a registry's plugin fragments (cached). */
export function specSchemaFor(registry) {
  if (!composed.has(registry)) composed.set(registry, composeSpecSchema(SPEC_SCHEMA, registry));
  return composed.get(registry);
}

export function specProblems(spec, registry = kitRegistry()) {
  const p = validateSchema(spec, specSchemaFor(registry)).map((q) => `widgets.spec.json${q.path === "/" ? "" : q.path}: ${q.message}`);
  if (p.length) return p;
  const ids = (list) => new Set(list.map((x) => x.id));
  const dup = (list, where) => { const seen = new Set(); for (const x of list) { if (seen.has(x.id)) p.push(`${where}: id "${x.id}" is used twice`); seen.add(x.id); } };
  const aud = ids(spec.audiences), uc = ids(spec.useCases), src = new Set(Object.keys(spec.sources));
  dup(spec.audiences, "audiences"); dup(spec.useCases, "useCases"); dup(spec.scenarios, "scenarios");
  for (const u of spec.useCases) {
    for (const a of u.audiences) if (!aud.has(a)) p.push(`useCases.${u.id}: unknown audience "${a}"`);
    for (const s of u.sources || []) if (!src.has(s)) p.push(`useCases.${u.id}: unknown source "${s}"`);
    if (!spec.scenarios.some((s) => s.useCase === u.id)) p.push(`useCases.${u.id}: no scenario shows this use case`);
  }
  for (const a of spec.audiences) if (!spec.scenarios.some((s) => s.audiences.includes(a.id))) p.push(`audiences.${a.id}: no scenario is for this audience`);
  const widgetIds = new Set();
  for (const s of spec.scenarios) {
    const w = `scenarios.${s.id}`;
    if (!uc.has(s.useCase)) p.push(`${w}: unknown use case "${s.useCase}"`);
    for (const a of s.audiences) if (!aud.has(a)) p.push(`${w}: unknown audience "${a}"`);
    const act = ids(s.actors); dup(s.actors, `${w}.actors`); dup(s.steps, `${w}.steps`);
    for (const st of s.steps) {
      if (!act.has(st.actor)) p.push(`${w}.steps.${st.id}: unknown actor "${st.actor}"`);
      if (st.to && !act.has(st.to)) p.push(`${w}.steps.${st.id}: unknown actor "${st.to}" (to)`);
      if (st.operation && !src.has(st.operation.split("#")[0])) p.push(`${w}.steps.${st.id}: unknown source in operation "${st.operation}"`);
    }
    for (const x of s.screens || []) if (!act.has(x.actor)) p.push(`${w}.screens.${x.id}: unknown actor "${x.actor}"`);
    // what only an archetype knows about its own scenario keys (devices, …): its validate hook, when the scenario holds its key or asks for it
    for (const pl of registry.plugins()) {
      if (typeof pl.validate !== "function") continue;
      if ((pl.spec?.key && s[pl.spec.key] !== undefined) || s.widgets.some((x) => x.archetype === pl.id)) p.push(...pl.validate(s, spec));
    }
    for (const x of s.widgets) {
      if (!registry.has(x.archetype)) p.push(`${w}: archetype "${x.archetype}" is not registered (${registry.ids().join(", ")}); a project's own plugins are declared in widgets.spec.json "plugins"`);
      else if (!spec.archetypes.includes(x.archetype)) p.push(`${w}: archetype "${x.archetype}" is not one of this project's archetypes (${spec.archetypes.join(", ")})`);
      const id = x.id || `${s.id}-${x.archetype}`;
      if (widgetIds.has(id)) p.push(`${w}: widget id "${id}" is used twice`);
      widgetIds.add(id);
    }
    walkSourced(s, (v, where) => {
      const id = v.$ref ? v.$ref.split("#")[0] : v.$engine.source;
      if (!src.has(id)) p.push(`${w}${where}: unknown source "${id}"`);
    });
  }
  for (const sc of spec.scenarios) for (const pl of registry.keyed()) if (pl.spec.requiresWidget && sc[pl.spec.key] !== undefined && !sc.widgets.some((x) => x.archetype === pl.id)) p.push(`scenarios.${sc.id}: has a ${pl.spec.key} but no widget of archetype ${pl.id}`);
  for (const a of spec.archetypes) if (!registry.has(a)) p.push(`archetypes: "${a}" is not registered (${registry.ids().join(", ")})`);
  for (const a of spec.archetypes) if (!spec.scenarios.some((s) => s.widgets.some((x) => x.archetype === a))) p.push(`archetypes: "${a}" is listed but no scenario uses it`);
  for (const e of spec.build.exports || []) if (!widgetIds.has(e.widget)) p.push(`build.exports: unknown widget "${e.widget}"`);
  const exported = new Set((spec.build.exports || []).map((e) => e.widget));
  for (const sc of spec.scenarios) for (const x of sc.widgets) {
    const id = x.id || `${sc.id}-${x.archetype}`, at = `scenarios.${sc.id}.widgets.${id}`;
    for (const u of x.usage.surfaces) if (u.placement === "page" && u.path !== spec.build.page?.path) p.push(`${at}: usage on page ${u.path}, but build.page.path is ${spec.build.page?.path ?? "not set"}`);
    // a widget placed only on the widgets page must list it; one placed in a section of another page may stay off it
    if (spec.build.page && !x.usage.surfaces.some((u) => u.placement === "page" && u.path === spec.build.page.path) && !x.usage.surfaces.some((u) => u.placement === "section")) p.push(`${at}: usage must list the widgets page (${spec.build.page.path}, placement page) or a section of a page`);
    // a widget exported as a kind (build.exports) is placed where its archetype's exportUsage says
    const exp = (spec.build.exports || []).find((e) => e.widget === id);
    const usage = registry.has(x.archetype) ? registry.get(x.archetype).exportUsage?.[exp?.as] : null;
    const owners = exp ? registry.exporters(exp.as).map((q) => q.id) : [];
    if (exp && owners.length && !owners.includes(x.archetype) && registry.plugins().some((q) => q.exportUsage?.[exp.as]?.archetypeOnly)) p.push(`${at}: exported as ${exp.as}, so its archetype must be ${owners.join(" or ")}`);
    if (usage) { if (!x.usage.surfaces.some((u) => u.placement === usage.placement)) p.push(`${at}: ${usage.message || `exported as ${exp.as}, so usage must list it (placement ${usage.placement})`}`); }
    else if (exp && exported.has(id) && !owners.length) p.push(`${at}: build.exports "${exp.as}" is produced by no registered archetype`);
  }
  return p;
}

function walkSourced(v, fn, where = "") {
  if (Array.isArray(v)) v.forEach((x, i) => walkSourced(x, fn, `${where}/${i}`));
  else if (isObj(v)) {
    if (typeof v.$ref === "string" || isObj(v.$engine)) fn(v, where);
    else for (const [k, x] of Object.entries(v)) walkSourced(x, fn, `${where}/${k}`);
  }
}

/** A text resolver for one locale. */
function textResolver(spec, sources, engine, code) {
  const def = spec.locales[0].code;
  const fromMap = (m) => m[code] ?? m[def] ?? Object.values(m)[0];
  const text = async function text(v) {
    if (v == null) return undefined;
    if (typeof v === "string") return v;
    if (typeof v === "number" || typeof v === "boolean") return v;
    let out;
    if (typeof v.$ref === "string") out = sourceRef(sources, v.$ref).value;
    else if (isObj(v.$engine)) out = await engine(v.$engine, code);
    else return fromMap(v);
    if (isObj(out)) out = fromMap(out);
    if (out == null || (typeof out === "object")) throw new Error(`a sourced text resolved to ${JSON.stringify(out)} (needs a string, a number or a {locale: string} map)`);
    return plain(out);
  };
  text.engine = (req) => engine(req, code);
  return text;
}

async function resolveScenario(spec, sc, text, asOf, sources, locale, registry) {
  const T = async (v) => text(v);
  const raw = async (v) => (typeof v.$ref === "string" ? sourceRef(sources, v.$ref).value : text.engine(v.$engine));
  const list = async (xs, f) => Promise.all((xs || []).map(f));
  const when = async (at) => {
    if (at == null) return undefined;
    if (typeof at === "string") { const m = /^([+-]\d+)d$/.exec(at); return m ? addDays(asOf, +m[1]) : at; }
    const v = await T(at);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(v))) throw new Error(`scenarios.${sc.id}: "at" resolved to ${JSON.stringify(v)}, not an ISO date`);
    return v;
  };
  const value = async (v) => (typeof v === "number" || typeof v === "boolean" ? v : T(v));
  const lines = (xs) => list(xs, async (l) => ({ ...(l.id ? { id: l.id } : {}), label: await T(l.label), value: await value(l.value), ...(l.tone ? { tone: l.tone } : {}) }));
  const out = {
    id: sc.id, useCase: sc.useCase, audiences: sc.audiences,
    title: await T(sc.title), summary: await T(sc.summary), honesty: sc.honesty,
    actors: await list(sc.actors, async (a) => ({ id: a.id, kind: a.kind, label: await T(a.label), role: await T(a.role), sees: a.sees ? await list(a.sees, T) : undefined })),
    inputs: await list(sc.inputs, async (i) => ({ ...i, label: await T(i.label), unit: await T(i.unit), options: i.options ? await list(i.options, async (o) => ({ value: o.value, label: await T(o.label) })) : undefined })),
    steps: await list(sc.steps, async (s) => ({
      id: s.id, actor: s.actor, to: s.to, status: s.status, decision: s.decision, event: s.event, icon: s.icon, channels: s.channels, fails: s.fails,
      device: s.device, initiator: s.initiator,
      scene: s.scene ? { kind: s.scene.kind, title: await T(s.scene.title), hash: await T(s.scene.hash), items: await list(s.scene.items, async (x) => ({ label: await T(x.label), value: await value(x.value), tone: x.tone })) } : undefined,
      action: await T(s.action), detail: await T(s.detail), outcome: await T(s.outcome), chip: await T(s.chip), at: await when(s.at),
      rules: s.rules ? await list(s.rules, T) : undefined,
      fields: s.fields ? await lines(s.fields) : undefined,
      actions: s.actions ? await list(s.actions, async (a) => ({ label: await T(a.label), result: await T(a.result), done: await T(a.done), title: await T(a.title), tone: a.tone || "ok", kind: a.kind, by: a.by })) : undefined,
      op: s.operation ? { ...operation(sources, s.operation, { asOf, request: s.request }), operation: s.operation, ...(s.payload ? { response: await raw(s.payload) } : {}) } : undefined,
    })),
    outcomes: await list(sc.outcomes, async (o) => ({ id: o.id, label: await T(o.label), expr: o.expr, unit: await T(o.unit), decimals: o.decimals, text: await T(o.text),
      bands: o.bands ? await list(o.bands, async (b) => ({ min: b.min, label: await T(b.label), text: await T(b.text) })) : undefined })),
    compare: sc.compare ? {
      columns: await list(sc.compare.columns, async (c) => ({ id: c.id, label: await T(c.label) })),
      rows: await list(sc.compare.rows, async (r) => ({ label: await T(r.label), cells: Object.fromEntries(await Promise.all(Object.entries(r.cells).map(async ([k, v]) => [k, await value(v)]))) })),
    } : undefined,
    screens: sc.screens ? await list(sc.screens, async (x) => ({ id: x.id, actor: x.actor, title: await T(x.title), lines: await lines(x.lines), cta: await T(x.cta),
      regions: x.regions ? await list(x.regions, async (r) => ({ id: r.id, label: await T(r.label) })) : undefined })) : undefined,
  };
  // what an archetype owns of the scenario (its spec key): resolved by its own hook, or guided by its schema fragment
  const ctx = { T, text, raw, list, lines, value, asOf, locale, sources, sc: out };
  for (const pl of registry.keyed()) {
    const raw0 = sc[pl.spec.key];
    if (raw0 === undefined) continue;
    const hook = pl.spec.resolve;
    out[pl.spec.key] = hook ? await hook(raw0, ctx) : await resolveBySchema(raw0, specSchemaFor(registry).$defs[`plugin.${pl.id}`], { T, raw, defs: specSchemaFor(registry).$defs });
  }
  return out;
}

/** Drop undefined values (stable JSON, no "undefined" keys). */
const clean = (v) => JSON.parse(JSON.stringify(v));

/** Build the generated widgets of a spec. Throws with every problem when the spec is invalid. */
export async function buildWidgets(specPath, { registry: given } = {}) {
  const { spec, text: specText, dir } = loadSpec(specPath);
  const registry = given || await registryFor(spec, dir);
  const problems = [...specProblems(spec, registry), ...fileProblems(spec, dir)];
  if (problems.length) { const e = new Error(`widgets.spec.json has problems:\n  - ${problems.join("\n  - ")}`); e.problems = problems; throw e; }
  const asOf = spec.build.asOf;
  const sources = await loadSources(spec, dir);
  const calls = [];
  const engine = engineCaller(sources, { asOf, calls });
  const locales = spec.locales.map((l) => ({ code: l.code, dir: l.dir, digits: l.digits || DIGITS[l.code.slice(0, 2)] || "latn", intl: l.intl || l.code }));
  const labelsOut = {};
  const widgets = [];
  const page = {};
  const exportsOut = {};
  const resolved = {};
  for (const loc of locales) {
    const text = textResolver(spec, sources, engine, loc.code);
    const labels = { live: await text(spec.honesty.labels.live), engine: await text(spec.honesty.labels.engine), sample: await text(spec.honesty.labels.sample) };
    labelsOut[loc.code] = labels;
    const useCases = await Promise.all(spec.useCases.map(async (u) => ({ id: u.id, label: await text(u.label), summary: await text(u.summary) })));
    const audiences = await Promise.all(spec.audiences.map(async (a) => ({ id: a.id, label: await text(a.label) })));
    const scList = [];
    for (const [si, raw] of spec.scenarios.entries()) {
      let sc;
      try { sc = await resolveScenario(spec, raw, text, asOf, sources, loc, registry); } catch (e) { throw new Error(`scenarios.${raw.id} (${loc.code}): ${e.message}`); }
      scList.push({ id: raw.id, title: sc.title, summary: sc.summary });
      resolved[`${raw.id}/${loc.code}`] = sc;
      for (const [wi, w] of raw.widgets.entries()) {
        const def = registry.get(w.archetype);
        const need = def.needs(sc);
        if (need) throw new Error(`scenarios.${raw.id}: the ${w.archetype} widget ${need}`);
        let data;
        try { data = def.derive(sc, { asOf }); } catch (e) { throw new Error(`scenarios.${raw.id}: ${w.archetype}: ${e.message}`); }
        const trace = [`spec#/scenarios/${si}`, `spec#/scenarios/${si}/widgets/${wi}`,
          ...raw.steps.flatMap((s, i) => (s.operation ? [sc.steps[i].op.trace] : []))];
        walkSourced(raw, (v) => { if (v.$ref) trace.push(v.$ref); else trace.push(`${v.$engine.source}#/${v.$engine.call}`); });
        widgets.push(clean({
          id: w.id || `${raw.id}-${w.archetype}`, archetype: w.archetype, scenario: raw.id, useCase: raw.useCase, audiences: raw.audiences,
          locale: loc.code, honesty: w.honesty || raw.honesty || spec.honesty.default,
          title: w.title ? await text(w.title) : sc.title, summary: sc.summary, data, trace: [...new Set(trace)],
          usage: { surfaces: await Promise.all(w.usage.surfaces.map(async (u) => ({ path: u.path, placement: u.placement, how: await text(u.how) }))) },
          application: { surface: await text(w.application.surface), href: w.application.href },
          architecture: { components: await Promise.all(w.architecture.components.map(text)), flow: await text(w.architecture.flow), diagram: w.architecture.diagram,
            url: `${spec.project.repo}/blob/main/${w.architecture.diagram.replace(/\.mmd$/, ".png")}` },
          utility: { learns: await text(w.utility.learns), does: await text(w.utility.does) },
        }));
      }
    }
    if (spec.build.page) page[loc.code] = clean({ path: spec.build.page.path, title: await text(spec.build.page.title), intro: await text(spec.build.page.intro), useCases, audiences, scenarios: scList });
    for (const e of spec.build.exports || []) {
      const w = widgets.find((x) => x.id === e.widget && x.locale === loc.code);
      const owners = registry.exporters(e.as);
      if (!owners.length) throw new Error(`build.exports: nothing produces "${e.as}" (archetypes that export: ${registry.plugins().flatMap((q) => Object.keys(q.exports || {}).map((k) => `${q.id}:${k}`)).join(", ") || "none"})`);
      const pl = owners.find((q) => q.id === w.archetype);
      if (!pl) throw new Error(`build.exports: ${e.as} needs a ${owners.map((q) => q.id).join(" or ")} widget (${e.widget} is ${w.archetype})`);
      exportsOut[e.as] ??= {};
      exportsOut[e.as][loc.code] = await pl.exports[e.as](w, e, { text, asOf, scenario: resolved[`${w.scenario}/${loc.code}`], locale: loc });
    }
  }
  const generated = stable(clean({
    schema: GENERATED_SCHEMA, generator: "kit widgets build", notice: NOTICE, project: spec.project.key, asOf,
    inputs: { spec: sha16(specText), sources: Object.fromEntries(Object.values(sources).map((s) => [s.id, s.hash])), engine: ENGINE_VERSION },
    locales, labels: labelsOut, calls: calls.length ? calls : undefined, page: Object.keys(page).length ? page : undefined,
    exports: Object.keys(exportsOut).length ? exportsOut : undefined, widgets,
  }));
  const json = `${JSON.stringify(generated, null, 2)}\n`;
  return { generated, json, out: resolve(dir, spec.build.out), spec, dir, registry };
}

/** Files the spec points at that must exist: every widget's architecture diagram. */
export function fileProblems(spec, dir) {
  const p = [];
  for (const sc of spec.scenarios || []) for (const x of sc.widgets || []) {
    const d = x.architecture?.diagram;
    if (d && !existsSync(resolve(dir, d))) p.push(`scenarios.${sc.id}: architecture.diagram ${d} does not exist (commit the project's diagram under docs/diagrams/)`);
  }
  return p;
}
